public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    if (!file.exists()) {
        return; // No need to schedule for deletion if the file does not exist
    }

    // Register a shutdown hook to delete the file or directory
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursively(file);
        } catch (IOException e) {
            // Logging the exception can be considered in a real-world application
            // For this method, we will just let it fail silently as per the method signature
        }
    }));
}

private static void deleteRecursively(File file) throws IOException {
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                deleteRecursively(f);
            }
        }
    }
    if (!file.delete()) {
        throw new IOException("Failed to delete " + file.getAbsolutePath());
    }
}

