private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, parse the argument types
        index = 1; // Start after '('
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
    } else {
        // It's a type descriptor, pop the single type
        popType(descriptor, index);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
            // These types take up one slot
            index++;
            break;
        case 'D':
        case 'J':
            // These types take up two slots
            index += 2;
            break;
        case 'L':
            // Object type, read until ';' is found
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++; // Move past ';'
            break;
        case '[':
            // Array type, skip all '[' and then parse the component type
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

