    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Type must be Character or char");
    }

    if (value == null) {
        throw new NullPointerException("Value cannot be null");
    }

    if (value instanceof Character) {
        return value;
    } else if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new IllegalArgumentException("String must have exactly one character");
        }
        return str.charAt(0);
    } else if (value instanceof Number) {
        Number num = (Number) value;
        int intValue = num.intValue();
        if (intValue < Character.MIN_VALUE || intValue > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Number is out of char range");
        }
        return (char) intValue;
    }

    throw new IllegalArgumentException("Value of type " + value.getClass().getName() + " cannot be converted to Character");
}

