final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        if (constantPoolEntryIndex <= 0 || classFileBuffer == null) {
            throw new IllegalArgumentException("Invalid constant pool index or classFileBuffer is null");
        }

        int utf8LengthIndex = constantPoolEntryIndex + 1;
        if (utf8LengthIndex + 2 > classFileBuffer.length) {
            throw new IllegalStateException("Invalid class file format: insufficient data for UTF8 length");
        }

        int utf8Length = (classFileBuffer[utf8LengthIndex] & 0xFF) << 8 | (classFileBuffer[utf8LengthIndex + 1] & 0xFF);
        int utf8DataIndex = utf8LengthIndex + 2;

        if (utf8DataIndex + utf8Length > classFileBuffer.length) {
            throw new IllegalStateException("Invalid class file format: insufficient data for UTF8 string");
        }

        int charIndex = 0;
        for (int i = utf8DataIndex; i < utf8DataIndex + utf8Length; ) {
            int utf8Byte = classFileBuffer[i++] & 0xFF;
            if (utf8Byte < 0x80) {
                charBuffer[charIndex++] = (char) utf8Byte;
            } else if (utf8Byte < 0xE0) {
                if (i >= utf8DataIndex + utf8Length) {
                    throw new IllegalStateException("Invalid UTF8 sequence");
                }
                int utf8Byte2 = classFileBuffer[i++] & 0xFF;
                charBuffer[charIndex++] = (char) (((utf8Byte & 0x1F) << 6) | (utf8Byte2 & 0x3F));
            } else if (utf8Byte < 0xF0) {
                if (i + 1 >= utf8DataIndex + utf8Length) {
                    throw new IllegalStateException("Invalid UTF8 sequence");
                }
                int utf8Byte2 = classFileBuffer[i++] & 0xFF;
                int utf8Byte3 = classFileBuffer[i++] & 0xFF;
                charBuffer[charIndex++] = (char) (((utf8Byte & 0x0F) << 12) | ((utf8Byte2 & 0x3F) << 6) | (utf8Byte3 & 0x3F));
            } else {
                throw new IllegalStateException("Invalid UTF8 sequence");
            }
        }
        return new String(charBuffer, 0, charIndex);
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalStateException("Invalid class file format: array index out of bounds", e);
    }
}

