public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("Name start index cannot be negative");
    }
    String name = buf.toString();
    if (nameStart >= name.length()) {
        throw new IllegalArgumentException("Name start index is out of bounds");
    }
    String[] parts = name.substring(nameStart).split("\\s+");
    if (parts.length > 0) {
        buf.setLength(nameStart);
        buf.append(parts[0]);
        for (int i = 1; i < parts.length; i++) {
            if (!parts[i].isEmpty()) {
                buf.append(' ').append(parts[i].charAt(0)).append('.');
            }
        }
    }
}

