public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the paths by ensuring they use "/" as the separator
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to process the components
    Stack<String> stack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(component);
            }
        }
    }

    for (String component : relativePathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(component);
            }
        }
    }

    // Reassemble the path
    StringBuilder result = new StringBuilder();
    for (String component : stack) {
        if (result.length() > 0) {
            result.append("/");
        }
        result.append(component);
    }

    // Ensure the path starts with a slash if the original path did
    if (!path.isEmpty() && path.charAt(0) == '/' && result.length() > 0 && result.charAt(0) != '/') {
        result.insert(0, '/');
    }

    return result.toString();
}

